#!/usr/bin/env python3
# Autonomously generated by an AI agent.
"""Evaluate beat grids against explicitly verified, versioned annotations."""

import argparse
import bisect
from collections import Counter
import hashlib
import json
import math
from pathlib import Path
import statistics

LABEL_MEMBERSHIP_TOLERANCE_SECONDS = 0.0001


def _fail(message):
    raise ValueError(message)


def _number(value, label, minimum=0):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        _fail(f"{label} must be a number")
    try:
        number = float(value)
    except OverflowError:
        _fail(f"{label} is outside the finite numeric range")
    if not math.isfinite(number) or number < minimum:
        _fail(f"{label} must be finite and >= {minimum}")
    return number


def _text(value, label):
    if not isinstance(value, str) or not value.strip():
        _fail(f"{label} must be nonempty text")
    return value


def _object(value, label):
    if not isinstance(value, dict):
        _fail(f"{label} must be an object")
    return value


def _digest(value):
    _text(value, "audio_sha256")
    if len(value) != 64 or any(
        c not in "0123456789abcdef" for c in value.lower()
    ):
        _fail("audio_sha256 must be a hexadecimal SHA-256 digest")
    return value.lower()


def _json_digest(value):
    return hashlib.sha256(
        json.dumps(
            value, sort_keys=True, separators=(",", ":"), allow_nan=False
        ).encode("utf-8")
    ).hexdigest()


def _file_digest(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _unique_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            _fail(f"Duplicate JSON key: {key}")
        result[key] = value
    return result


def read_json(path):
    with Path(path).open(encoding="utf-8") as stream:
        return json.load(
            stream,
            object_pairs_hook=_unique_pairs,
            parse_constant=lambda token: _fail(
                f"Non-finite JSON value: {token}"
            ),
        )


def _version(document, label):
    _object(document, label)
    value = document.get("version")
    if type(value) is not int or value != 1:
        _fail(f"{label} requires version 1")


def _records(document, label):
    records = document.get("tracks")
    if not isinstance(records, list):
        _fail(f"{label}.tracks must be an array")
    result = {}
    for record in records:
        _object(record, label + ".track")
        identifier = _text(record.get("id"), "track id")
        if identifier in result:
            _fail(f"Duplicate track id: {identifier}")
        result[identifier] = record
    return result


def _positions(value, duration, label):
    if not isinstance(value, list):
        _fail(f"{label} must be an array")
    result = [_number(item, label) for item in value]
    if any(item > duration for item in result):
        _fail(f"{label} extends beyond the recording")
    if any(a >= b for a, b in zip(result, result[1:])):
        _fail(f"{label} must be strictly increasing")
    return result


def _intervals(value, duration):
    if value is None:
        return [[0.0, duration]]
    if not isinstance(value, list) or not value:
        _fail("annotation intervals must be a nonempty array")
    result = []
    for pair in value:
        if not isinstance(pair, list) or len(pair) != 2:
            _fail("each annotation interval needs start and end")
        start, end = [_number(item, "interval boundary") for item in pair]
        if (
            start >= end
            or end > duration
            or (result and start < result[-1][1])
        ):
            _fail(
                "annotation intervals must be ordered, disjoint and in range"
            )
        result.append([start, end])
    return result


def _inside(position, intervals):
    for index, (start, end) in enumerate(intervals):
        if start <= position < end:
            return index
    return None


def _selected_positions(values, intervals):
    return [value for value in values if _inside(value, intervals) is not None]


def _zones(data, duration):
    if "bpm" in data and "tempo_zones" in data:
        _fail("supply bpm or tempo_zones, not both")
    if "bpm" in data:
        bpm = _number(data["bpm"], "bpm", 0.001)
        return [{"start": 0.0, "end": duration, "bpm": bpm}]
    if "tempo_zones" not in data:
        return None
    if not isinstance(data["tempo_zones"], list) or not data["tempo_zones"]:
        _fail("tempo_zones must be a nonempty array")
    result = []
    for zone in data["tempo_zones"]:
        _object(zone, "tempo zone")
        start = _number(zone.get("start"), "tempo zone start")
        end = _number(zone.get("end"), "tempo zone end")
        bpm = _number(zone.get("bpm"), "tempo zone bpm", 0.001)
        if (
            start >= end
            or end > duration
            or (result and start < result[-1]["end"])
        ):
            _fail("tempo zones must be ordered, disjoint and in range")
        result.append({"start": start, "end": end, "bpm": bpm})
    return result


def _quantile(values, fraction):
    if not values:
        return None
    values = sorted(values)
    index = (len(values) - 1) * fraction
    low = int(index)
    return values[low] + (
        values[min(low + 1, len(values) - 1)] - values[low]
    ) * (index - low)


def _error_statistics(errors):
    absolute = [abs(error) for error in errors]
    return {
        "mean_signed_ms": statistics.fmean(errors) if errors else None,
        "median_signed_ms": _quantile(errors, 0.5),
        "mae_ms": statistics.fmean(absolute) if errors else None,
        "p95_abs_ms": _quantile(absolute, 0.95),
        "p99_abs_ms": _quantile(absolute, 0.99),
        "max_abs_ms": max(absolute) if absolute else None,
    }


def match_positions(reference, predicted, tolerance):
    """Maximize ordered matches, then minimize total absolute error."""
    # Sparse dynamic programming avoids a quadratic matrix for long DJ sets.
    # Fenwick states maximize (match count, negative error), with parent links.
    tree = [(0, 0.0, -1)] * (len(predicted) + 1)
    nodes = []

    def query(index):
        best = (0, 0.0, -1)
        while index:
            best = max(best, tree[index])
            index -= index & -index
        return best

    def update(index, state):
        while index < len(tree):
            tree[index] = max(tree[index], state)
            index += index & -index

    for index, position in enumerate(reference):
        first = bisect.bisect_left(predicted, position - tolerance - 1e-12)
        last = bisect.bisect_right(predicted, position + tolerance + 1e-12)
        updates = []
        for candidate in range(first, last):
            previous = query(candidate)
            node = len(nodes)
            if node >= 2_000_000:
                _fail("prediction timestamps are too dense for beat matching")
            nodes.append((previous[2], index, candidate))
            updates.append(
                (
                    candidate + 1,
                    (
                        previous[0] + 1,
                        previous[1] - abs(predicted[candidate] - position),
                        node,
                    ),
                )
            )
        for candidate, state in updates:
            update(candidate, state)
    node = query(len(predicted))[2]
    matches = []
    while node != -1:
        node, index, candidate = nodes[node]
        matches.append((index, candidate))
    return list(reversed(matches))


def beat_metrics(reference, predicted, intervals, tolerance_ms, stable_ms):
    reference = _selected_positions(reference, intervals)
    if not reference:
        return None
    # Boundary collars make early and late timing errors symmetric. An event
    # outside annotation intervals counts only if matched to an annotated beat.
    # Global one-to-one matching prevents double use where collars overlap.
    tolerance = tolerance_ms / 1000
    predicted = [
        value
        for value in predicted
        if any(
            start - tolerance - 1e-12 <= value <= end + tolerance + 1e-12
            for start, end in intervals
        )
    ]
    matches = match_positions(reference, predicted, tolerance)
    errors = [(predicted[j] - reference[i]) * 1000 for i, j in matches]
    matched_predicted = {j for _, j in matches}
    scored_predicted = matched_predicted | {
        index
        for index, value in enumerate(predicted)
        if _inside(value, intervals) is not None
    }
    stable = [False] * len(reference)
    for (index, _), error in zip(matches, errors):
        stable[index] = abs(error) <= stable_ms + 1e-9
    duplicates = 0
    for index, position in enumerate(predicted):
        if index in matched_predicted or index not in scored_predicted:
            continue
        near = bisect.bisect_left(reference, position)
        choices = [i for i in (near - 1, near) if 0 <= i < len(reference)]
        nearest = min(choices, key=lambda i: abs(reference[i] - position))
        duplicates += abs(reference[nearest] - position) <= tolerance_ms / 1000
        if _inside(reference[nearest], intervals) == _inside(
            position, intervals
        ):
            stable[nearest] = False
    longest_stable = longest_failure = run = 0
    longest_seconds = 0.0
    run_start = 0
    for index, good in enumerate(stable):
        same_interval = index > 0 and _inside(
            reference[index], intervals
        ) == _inside(reference[index - 1], intervals)
        if index and good == stable[index - 1] and same_interval:
            run += 1
        else:
            run = 1
            run_start = index
        if good:
            longest_stable = max(longest_stable, run)
            longest_seconds = max(
                longest_seconds, reference[index] - reference[run_start]
            )
        else:
            longest_failure = max(longest_failure, run)
    true_positive = len(matches)
    precision = (
        true_positive / len(scored_predicted) if scored_predicted else 0.0
    )
    recall = true_positive / len(reference)
    return {
        "reference_beats": len(reference),
        "predicted_beats": len(scored_predicted),
        "matched_beats": true_positive,
        "missing_beats": len(reference) - true_positive,
        "extra_beats": len(scored_predicted) - true_positive,
        "duplicate_beats": duplicates,
        "precision": precision,
        "recall": recall,
        "f1": (
            2 * precision * recall / (precision + recall)
            if precision + recall
            else 0
        ),
        **_error_statistics(errors),
        "stable_beats": sum(stable),
        "stable_beat_fraction": sum(stable) / len(stable),
        "longest_stable_run_beats": longest_stable,
        "longest_stable_seconds": longest_seconds,
        "longest_failure_run_beats": longest_failure,
        "continuous": all(stable) and true_positive == len(scored_predicted),
        "_errors_ms": errors,
    }


def tempo_metrics(reference, predicted, intervals, tolerance):
    if reference is None or predicted is None:
        return None
    total = covered = correct = weighted_error = 0.0
    maximum = None
    for zone in reference:
        for start, end in intervals:
            left, right = max(start, zone["start"]), min(end, zone["end"])
            if right <= left:
                continue
            total += right - left
            for candidate in predicted:
                overlap = min(right, candidate["end"]) - max(
                    left, candidate["start"]
                )
                if overlap <= 0:
                    continue
                error = abs(candidate["bpm"] - zone["bpm"])
                covered += overlap
                weighted_error += overlap * error
                maximum = error if maximum is None else max(maximum, error)
                if error <= tolerance + 1e-12:
                    correct += overlap
    if not total:
        return None
    return {
        "reference_seconds": total,
        "covered_seconds": covered,
        "coverage_fraction": covered / total,
        "mae_bpm": weighted_error / covered if covered else None,
        "max_abs_bpm": maximum,
        "exact_fraction": correct / total,
        "within_tolerance": correct >= total - 1e-9,
    }


def _performance(record):
    timings = _object(record.get("timings_ms", {}), "timings_ms")
    timings = {
        _text(stage, "timing stage"): _number(value, "timing duration")
        for stage, value in timings.items()
    }
    result = {"timings_ms": timings}
    if "peak_rss_bytes" in record:
        value = record["peak_rss_bytes"]
        if type(value) is not int or value < 0:
            _fail("peak_rss_bytes must be a nonnegative integer")
        result["peak_rss_bytes"] = value
    if "decoder" in record:
        result["decoder"] = _object(record["decoder"], "decoder")
    return result


def _corrections(record):
    if "corrections" not in record:
        return None
    value = _object(record["corrections"], "corrections")
    if value.get("source") != "human":
        _fail(
            "corrections require source='human'; never infer correction effort"
        )
    result = {"source": "human"}
    for field in ("actions", "seconds"):
        if field in value:
            number = _number(value[field], "correction " + field)
            if field == "actions" and (type(value[field]) is not int):
                _fail("correction actions must be an integer")
            result[field] = number
    if len(result) == 1:
        _fail("corrections require measured actions or seconds")
    return result


def _run_measurements(candidate, rows):
    if "run_measurements" not in candidate:
        return None
    values = _object(candidate["run_measurements"], "run_measurements")
    result = {}
    for key, value in values.items():
        if key == "scope":
            result[key] = _text(value, "measurement scope")
        elif key.endswith("_bytes"):
            if type(value) is not int or value < 0:
                _fail("run byte measurements must be nonnegative integers")
            result[key] = value
        elif key.endswith("_ms"):
            result[key] = _number(value, "run measurement " + key)
        else:
            _fail("run measurements require scope or named _ms/_bytes fields")
    matches_selection = set(_records(candidate, "candidate")) == {
        row["id"] for row in rows
    }
    result["track_set_matches_selection"] = matches_selection
    wall = result.get("wall_ms") if matches_selection else None
    good = [
        row
        for row in rows
        if row["status"] not in ("analysis_error", "missing_prediction")
    ]
    result["successful_audio_seconds_per_wall_second"] = (
        sum(row["duration"] for row in good) / (wall / 1000) if wall else None
    )
    result["successful_tracks_per_hour"] = (
        len(good) * 3_600_000 / wall if wall else None
    )
    return result


def _annotation(track, base):
    if "annotations" in track and "annotation_file" in track:
        _fail("supply inline annotations or annotation_file")
    if "annotation_file" in track:
        return _object(
            read_json(
                base / _text(track["annotation_file"], "annotation_file")
            ),
            "annotation_file",
        )
    return (
        _object(track["annotations"], "annotations")
        if "annotations" in track
        else None
    )


def _prediction(record, base):
    if "prediction_file" not in record:
        return record
    loaded = _object(
        read_json(base / _text(record["prediction_file"], "prediction_file")),
        "prediction_file",
    )
    if loaded.get("id") != record["id"] or _digest(
        loaded.get("audio_sha256")
    ) != _digest(record.get("audio_sha256")):
        _fail("external prediction identity mismatch")
    return {**record, **loaded}


def _timeline(annotation, track, prediction):
    reference = (
        annotation.get("timeline_id", track.get("timeline_id"))
        if annotation
        else None
    )
    candidate = prediction.get("timeline_id")
    if reference is not None:
        _text(reference, "reference timeline_id")
    if candidate is not None:
        _text(candidate, "prediction timeline_id")
    if "reference_offset_seconds" in prediction:
        offset = _number(
            prediction["reference_offset_seconds"],
            "reference offset",
            -track["duration"],
        )
        if offset > track["duration"]:
            _fail("reference offset exceeds recording duration")
        if (
            not reference
            or not candidate
            or prediction.get("reference_timeline_id") != reference
        ):
            _fail(
                "an explicit offset needs source and matching "
                "reference timeline ids"
            )
        return (
            True,
            offset,
            {
                "reference": reference,
                "prediction": candidate,
                "reference_offset_seconds": offset,
            },
        )
    known = bool(reference and candidate and reference == candidate)
    return (
        known,
        0.0,
        {
            "reference": reference,
            "prediction": candidate,
            "reference_offset_seconds": None,
        },
    )


def _mode(record):
    value = record.get("grid_mode")
    if value is not None and value not in ("constant", "variable"):
        _fail("grid_mode must be constant or variable")
    if "constant" in record:
        if type(record["constant"]) is not bool:
            _fail("constant must be a boolean")
        flag = "constant" if record["constant"] else "variable"
        if value is not None and value != flag:
            _fail("constant and grid_mode disagree")
        value = flag
    return value


def _reference_data(annotation, duration):
    intervals = _intervals(annotation.get("intervals"), duration)
    references = {
        key: _positions(annotation[key], duration, "reference " + key)
        for key in ("beats", "downbeats")
        if key in annotation
    }
    if "beats" in references and "downbeats" in references:
        if len(
            match_positions(
                references["downbeats"],
                references["beats"],
                LABEL_MEMBERSHIP_TOLERANCE_SECONDS,
            )
        ) != len(references["downbeats"]):
            _fail("reference downbeats must be a subset of beats")
    return (
        intervals,
        references,
        _zones(annotation, duration),
        _mode(annotation),
    )


def _failure_penalty(
    row, references, reference_tempo, reference_mode, intervals, options
):
    row["failure_penalty"] = True
    for key, positions in references.items():
        row["quality"][key] = beat_metrics(
            positions,
            [],
            intervals,
            options["match_tolerance_ms"],
            options["stable_tolerance_ms"],
        )
    row["quality"]["tempo"] = tempo_metrics(
        reference_tempo, [], intervals, options["bpm_tolerance"]
    )
    if reference_mode is not None:
        row["quality"]["grid_mode_correct"] = False


def _evaluate_track(
    track, raw_prediction, manifest_base, candidate_base, options
):
    duration = track["duration"]
    row = {
        "id": track["id"],
        "categories": track["categories"],
        "split": track["split"],
        "duration": duration,
        "status": "ok",
        "quality": {
            "beats": None,
            "downbeats": None,
            "tempo": None,
            "grid_mode_correct": None,
        },
        "unavailable": {},
        "performance": {"timings_ms": {}},
        "corrections": None,
    }
    annotation = _annotation(track, manifest_base)
    verified = (
        annotation is not None
        and annotation.get("status") == "manual_verified"
    )
    row["manual_verified"] = verified
    row["reference_sha256"] = (
        _json_digest(annotation) if annotation is not None else None
    )
    intervals, references, reference_tempo, reference_mode = (
        [],
        {},
        None,
        None,
    )
    if verified:
        intervals, references, reference_tempo, reference_mode = (
            _reference_data(annotation, duration)
        )
        row["reference_intervals"] = intervals
    if raw_prediction is None:
        row["status"] = "missing_prediction"
        row["unavailable"] = {
            key: "missing prediction" for key in row["quality"]
        }
        if verified:
            _failure_penalty(
                row,
                references,
                reference_tempo,
                reference_mode,
                intervals,
                options,
            )
        return row
    prediction = _prediction(raw_prediction, candidate_base)
    if _digest(prediction.get("audio_sha256")) != _digest(
        track["audio_sha256"]
    ):
        _fail(f"Audio identity mismatch: {track['id']}")
    row["performance"] = _performance(prediction)
    row["corrections"] = _corrections(prediction)
    if prediction.get("status", "ok") in ("error", "failed"):
        row["status"] = "analysis_error"
        row["error"] = _text(prediction.get("error"), "analysis error")
        row["unavailable"] = {key: "analysis failed" for key in row["quality"]}
        if verified:
            _failure_penalty(
                row,
                references,
                reference_tempo,
                reference_mode,
                intervals,
                options,
            )
        return row
    if prediction.get("status", "ok") != "ok":
        _fail("prediction status must be ok, error or failed")
    timeline_known, offset, row["timeline"] = _timeline(
        annotation, track, prediction
    )
    candidate_duration = prediction.get(
        "duration", prediction.get("decoder", {}).get("duration", duration)
    )
    candidate_duration = _number(
        candidate_duration, "prediction duration", 0.001
    )
    predicted = {}
    for key in ("beats", "downbeats"):
        if key in prediction:
            predicted[key] = [
                value + offset
                for value in _positions(
                    prediction[key], candidate_duration, "predicted " + key
                )
            ]
    if "beats" in predicted and "downbeats" in predicted:
        if len(
            match_positions(
                predicted["downbeats"],
                predicted["beats"],
                LABEL_MEMBERSHIP_TOLERANCE_SECONDS,
            )
        ) != len(predicted["downbeats"]):
            _fail("predicted downbeats must be a subset of beats")
    predicted_tempo = _zones(prediction, candidate_duration)
    predicted_mode = _mode(prediction)
    if predicted_tempo is not None:
        predicted_tempo = [
            {
                **zone,
                "start": zone["start"] + offset,
                "end": zone["end"] + offset,
            }
            for zone in predicted_tempo
        ]
    if not verified:
        row["status"] = "unannotated" if annotation is None else "unverified"
        row["unavailable"] = {
            key: "no manually verified reference" for key in row["quality"]
        }
        return row
    for key in ("beats", "downbeats"):
        if key not in references or key not in predicted:
            row["unavailable"][key] = "reference or prediction not supplied"
            continue
        if not timeline_known:
            row["unavailable"][key] = (
                "decoder timelines missing or different; "
                "explicit alignment required"
            )
            continue
        row["quality"][key] = beat_metrics(
            references[key],
            predicted[key],
            intervals,
            options["match_tolerance_ms"],
            options["stable_tolerance_ms"],
        )
        if row["quality"][key] is None:
            row["unavailable"][
                key
            ] = "no annotated events in evaluated intervals"
    if timeline_known or (
        "tempo_zones" not in annotation and "tempo_zones" not in prediction
    ):
        if "bpm" in prediction:
            predicted_tempo = _zones(prediction, duration)
        row["quality"]["tempo"] = tempo_metrics(
            reference_tempo,
            predicted_tempo,
            intervals,
            options["bpm_tolerance"],
        )
    if row["quality"]["tempo"] is None:
        row["unavailable"]["tempo"] = (
            "tempo-zone decoder timelines unresolved"
            if not timeline_known
            and ("tempo_zones" in annotation or "tempo_zones" in prediction)
            else "reference or prediction tempo not supplied"
        )
    if reference_mode is not None and predicted_mode is not None:
        row["quality"]["grid_mode_correct"] = reference_mode == predicted_mode
    elif reference_mode is not None:
        row["unavailable"][
            "grid_mode_correct"
        ] = "prediction grid mode not supplied"
    return row


def _summary(rows):
    result = {
        "selected_tracks": len(rows),
        "status_counts": dict(Counter(row["status"] for row in rows)),
        "manually_verified_tracks": sum(
            row["manual_verified"] for row in rows
        ),
    }
    modes = [
        row["quality"]["grid_mode_correct"]
        for row in rows
        if row["quality"]["grid_mode_correct"] is not None
    ]
    result["grid_mode"] = {
        "evaluated_tracks": len(modes),
        "correct_tracks": sum(modes),
        "accuracy": statistics.fmean(modes) if modes else None,
    }
    for key in ("beats", "downbeats"):
        metrics = [
            row["quality"][key]
            for row in rows
            if row["quality"][key] is not None
        ]
        if not metrics:
            result[key] = {"evaluated_tracks": 0, "metrics": None}
            continue
        reference = sum(metric["reference_beats"] for metric in metrics)
        predicted = sum(metric["predicted_beats"] for metric in metrics)
        matches = sum(metric["matched_beats"] for metric in metrics)
        errors = [
            error for metric in metrics for error in metric["_errors_ms"]
        ]
        result[key] = {
            "evaluated_tracks": len(metrics),
            "reference_beats": reference,
            "predicted_beats": predicted,
            "missing_beats": reference - matches,
            "extra_beats": predicted - matches,
            "micro_f1": (
                2 * matches / (reference + predicted)
                if reference + predicted
                else 0
            ),
            "macro_f1": statistics.fmean(metric["f1"] for metric in metrics),
            "stable_beat_fraction": sum(
                metric["stable_beats"] for metric in metrics
            )
            / reference,
            "continuous_tracks": sum(
                metric["continuous"] for metric in metrics
            ),
            "worst_failure_run_beats": max(
                metric["longest_failure_run_beats"] for metric in metrics
            ),
            **_error_statistics(errors),
        }
    tempos = [
        row["quality"]["tempo"]
        for row in rows
        if row["quality"]["tempo"] is not None
    ]
    total = sum(metric["reference_seconds"] for metric in tempos)
    covered = sum(metric["covered_seconds"] for metric in tempos)
    result["tempo"] = {
        "evaluated_tracks": len(tempos),
        "coverage_fraction": covered / total if total else None,
        "exact_fraction": (
            sum(
                metric["exact_fraction"] * metric["reference_seconds"]
                for metric in tempos
            )
            / total
            if total
            else None
        ),
        "mae_bpm": (
            sum(
                metric["mae_bpm"] * metric["covered_seconds"]
                for metric in tempos
                if metric["mae_bpm"] is not None
            )
            / covered
            if covered
            else None
        ),
        "all_within_tolerance_tracks": sum(
            metric["within_tolerance"] for metric in tempos
        ),
    }
    stages = sorted(
        {stage for row in rows for stage in row["performance"]["timings_ms"]}
    )
    timings = {}
    for stage in stages:
        values = [
            row["performance"]["timings_ms"][stage]
            for row in rows
            if stage in row["performance"]["timings_ms"]
        ]
        timings[stage] = {
            "measured_tracks": len(values),
            "sum_ms": sum(values),
            "median_ms": statistics.median(values),
            "p95_ms": _quantile(values, 0.95),
        }
    wall_rows = [
        row for row in rows if "wall" in row["performance"]["timings_ms"]
    ]
    wall = sum(row["performance"]["timings_ms"]["wall"] for row in wall_rows)
    good_rows = [
        row
        for row in wall_rows
        if row["status"] not in ("analysis_error", "missing_prediction")
    ]
    rss = [
        row["performance"]["peak_rss_bytes"]
        for row in rows
        if "peak_rss_bytes" in row["performance"]
    ]
    result["performance"] = {
        "timings_ms": timings,
        "wall_measured_tracks": len(wall_rows),
        "successful_wall_measured_tracks": len(good_rows),
        "audio_seconds_per_summed_track_wall_second": (
            sum(row["duration"] for row in good_rows) / (wall / 1000)
            if wall
            else None
        ),
        "successful_tracks_per_summed_wall_hour": (
            len(good_rows) * 3_600_000 / wall if wall else None
        ),
        "rss_measured_tracks": len(rss),
        "peak_rss_bytes_max": max(rss) if rss else None,
    }
    corrections = {}
    for field in ("actions", "seconds"):
        values = [
            row["corrections"][field]
            for row in rows
            if row["corrections"] and field in row["corrections"]
        ]
        corrections[field] = {
            "measured_tracks": len(values),
            "sum": sum(values) if values else None,
            "mean_per_measured_track": (
                statistics.fmean(values) if values else None
            ),
        }
    result["corrections"] = corrections
    return result


def evaluate(
    manifest,
    candidates,
    *,
    split="dev",
    match_tolerance_ms=70,
    stable_tolerance_ms=20,
    bpm_tolerance=0.1,
    manifest_base=None,
    candidate_bases=None,
    verify_audio=False,
    include_errors=False,
):
    _version(manifest, "manifest")
    if split not in ("dev", "holdout", "all"):
        _fail("split must be dev, holdout or all")
    options = {
        "match_tolerance_ms": _number(
            match_tolerance_ms, "match tolerance", 0.001
        ),
        "stable_tolerance_ms": _number(
            stable_tolerance_ms, "stability tolerance"
        ),
        "bpm_tolerance": _number(bpm_tolerance, "BPM tolerance"),
        "label_membership_tolerance_seconds": (
            LABEL_MEMBERSHIP_TOLERANCE_SECONDS
        ),
    }
    if options["stable_tolerance_ms"] > options["match_tolerance_ms"]:
        _fail("stability tolerance cannot exceed matching tolerance")
    tracks = _records(manifest, "manifest")
    selected = []
    for track in tracks.values():
        _digest(track.get("audio_sha256"))
        _number(track.get("duration"), "duration", 0.001)
        if track.get("split") not in ("dev", "holdout"):
            _fail("each track needs split dev or holdout")
        categories = track.get("categories")
        if not isinstance(categories, list) or not categories:
            _fail("each track needs category strata")
        for category in categories:
            _text(category, "category")
        if len(set(categories)) != len(categories):
            _fail("duplicate category on track")
        if split == "all" or track["split"] == split:
            selected.append(dict(track))
    manifest_base = Path(manifest_base or ".")
    for track in selected:
        annotation = _annotation(track, manifest_base)
        track.pop("annotation_file", None)
        if annotation is not None:
            track["annotations"] = annotation
    if verify_audio:
        for track in selected:
            path = manifest_base / _text(track.get("audio_file"), "audio_file")
            digest = _file_digest(path)
            if digest != _digest(track["audio_sha256"]):
                _fail(f"Audio file checksum mismatch: {track['id']}")
    output = {
        "version": 1,
        "dataset": manifest.get("dataset"),
        "split": split,
        "options": options,
        "selected_tracks": len(selected),
        "excluded_tracks": len(tracks) - len(selected),
        "candidates": [],
        "selected_reference_sha256": _json_digest(selected),
        "evaluator_sha256": _file_digest(__file__),
    }
    identities = set()
    for index, candidate in enumerate(candidates):
        _version(candidate, "candidate")
        identity = _object(candidate.get("candidate"), "candidate identity")
        name = _text(identity.get("name"), "candidate name")
        version = _text(identity.get("version"), "candidate version")
        if (name, version) in identities:
            _fail("candidate name/version must be unique")
        identities.add((name, version))
        predictions = _records(candidate, "candidate")
        if set(predictions) - set(tracks):
            _fail("candidate contains unknown track ids")
        base = Path(candidate_bases[index]) if candidate_bases else Path(".")
        rows = [
            _evaluate_track(
                track,
                predictions.get(track["id"]),
                manifest_base,
                base,
                options,
            )
            for track in selected
        ]
        groups = {
            part: _summary([row for row in rows if row["split"] == part])
            for part in ("dev", "holdout")
            if any(row["split"] == part for row in rows)
        }
        strata = {
            category: _summary(
                [row for row in rows if category in row["categories"]]
            )
            for category in sorted(
                {category for row in rows for category in row["categories"]}
            )
        }
        summary = _summary(rows)
        for row in rows:
            for metric in row["quality"].values():
                if isinstance(metric, dict) and "_errors_ms" in metric:
                    errors = metric.pop("_errors_ms")
                    if include_errors:
                        metric["signed_errors_ms"] = errors
        output["candidates"].append(
            {
                "candidate": identity,
                "summary": summary,
                "by_split": groups,
                "by_category": strata,
                "run_measurements": _run_measurements(candidate, rows),
                "tracks": rows,
            }
        )
    return output


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest", type=Path, required=True)
    parser.add_argument(
        "--candidate", type=Path, action="append", required=True
    )
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--split", choices=("dev", "holdout", "all"), default="dev"
    )
    parser.add_argument("--match-tolerance-ms", type=float, default=70)
    parser.add_argument("--stable-tolerance-ms", type=float, default=20)
    parser.add_argument("--bpm-tolerance", type=float, default=0.1)
    parser.add_argument("--verify-audio", action="store_true")
    parser.add_argument("--include-errors", action="store_true")
    args = parser.parse_args(argv)
    try:
        report = evaluate(
            read_json(args.manifest),
            [read_json(path) for path in args.candidate],
            split=args.split,
            match_tolerance_ms=args.match_tolerance_ms,
            stable_tolerance_ms=args.stable_tolerance_ms,
            bpm_tolerance=args.bpm_tolerance,
            manifest_base=args.manifest.parent,
            candidate_bases=[path.parent for path in args.candidate],
            verify_audio=args.verify_audio,
            include_errors=args.include_errors,
        )
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(
            json.dumps(report, indent=2, allow_nan=False) + "\n",
            encoding="utf-8",
        )
    except (ValueError, OSError) as error:
        parser.error(str(error))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
